export function checkActivityAnswer(stage,step,choice){const activity=extraActivities[stage],q=activity?.steps[step];if(!q||!q.options.some(([id])=>id===choice))throw new Error('Respuesta desconocida');return {correct:choice===q.answer,feedback:choice===q.answer?q.explanation:q.feedback[choice]};}
